// Portfolio 2.0 — Main Interactive Application Logic

document.addEventListener('DOMContentLoaded', () => {
  // Mark JS ready for smooth CSS reveal animations
  document.body.classList.add('js-ready');

  // Elements
  const progressBar = document.getElementById('progressBar');
  const heroScene = document.getElementById('heroScene');
  const motionToggle = document.getElementById('motionToggle');
  const motionText = document.getElementById('motionText');
  const motionIcon = document.getElementById('motionIcon');

  const manifestoSection = document.getElementById('manifesto');
  const manifestoOrbit = document.getElementById('manifestoOrbit');
  const manifestoPhrases = document.querySelectorAll('.manifesto-phrase');
  const manifestoCurrent = document.getElementById('manifestoCurrent');
  const manifestoProgress = document.getElementById('manifestoProgress');

  const workSlider = document.getElementById('workSlider');
  const slides = document.querySelectorAll('.slide');
  const tabButtons = document.querySelectorAll('.slider-tabs button');
  const prevSlideBtn = document.getElementById('prevSlide');
  const nextSlideBtn = document.getElementById('nextSlide');

  const labSection = document.getElementById('lab');
  const labObject = document.getElementById('labObject');
  const simArt = document.getElementById('simArt');

  // --- 1. Motion Toggle Handler ---
  let isMotionOff = localStorage.getItem('portfolio_motion_off') === 'true';

  function updateMotionState(off) {
    isMotionOff = off;
    if (isMotionOff) {
      document.body.classList.add('motion-off');
      if (motionText) motionText.textContent = 'MOTION: OFF';
      if (motionIcon) motionIcon.textContent = '⏸';
    } else {
      document.body.classList.remove('motion-off');
      if (motionText) motionText.textContent = 'MOTION: ON';
      if (motionIcon) motionIcon.textContent = '⚡';
    }
    localStorage.setItem('portfolio_motion_off', isMotionOff);
  }

  if (motionToggle) {
    updateMotionState(isMotionOff);
    motionToggle.addEventListener('click', () => {
      updateMotionState(!isMotionOff);
    });
  }

  // --- 2. 3D Mouse Parallax in Hero ---
  let mouseX = 0, mouseY = 0;
  let currentPx = 0, currentPy = 0;

  window.addEventListener('mousemove', (e) => {
    if (isMotionOff) return;
    mouseX = (e.clientX / window.innerWidth - 0.5) * 35;
    mouseY = (e.clientY / window.innerHeight - 0.5) * 35;
  });

  function animateHeroParallax() {
    if (!isMotionOff && heroScene) {
      currentPx += (mouseX - currentPx) * 0.08;
      currentPy += (mouseY - currentPy) * 0.08;
      heroScene.style.setProperty('--px', `${currentPx.toFixed(2)}px`);
      heroScene.style.setProperty('--py', `${currentPy.toFixed(2)}px`);
    }
    requestAnimationFrame(animateHeroParallax);
  }
  animateHeroParallax();

  // --- 3. Scroll Scrubbing & Choreography ---
  function onScroll() {
    const scrollY = window.scrollY;
    const windowHeight = window.innerHeight;
    const docHeight = document.documentElement.scrollHeight;

    // Progress Bar
    if (progressBar) {
      const scrollPercent = (scrollY / (docHeight - windowHeight)) * 100;
      progressBar.style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;
    }

    // Hero Drift & Blur
    if (heroScene) {
      const heroHeight = windowHeight;
      if (scrollY < heroHeight) {
        const heroRatio = scrollY / heroHeight;
        const drift = heroRatio * 60;
        const scale = 1 - heroRatio * 0.08;
        const blur = heroRatio * 8;
        heroScene.style.setProperty('--hero-drift', `${drift.toFixed(1)}px`);
        heroScene.style.setProperty('--hero-scale', `${scale.toFixed(3)}`);
        heroScene.style.setProperty('--hero-blur', `${blur.toFixed(1)}px`);
      }
    }

    // Manifesto Pinned Chapter Choreography
    if (manifestoSection) {
      const rect = manifestoSection.getBoundingClientRect();
      const totalDist = rect.height - windowHeight;
      if (totalDist > 0) {
        const progress = Math.min(1, Math.max(0, -rect.top / totalDist));

        // Orbit scale & rotation progress
        if (manifestoOrbit) {
          const orbitScale = 0.85 + progress * 0.35;
          manifestoOrbit.style.setProperty('--orbit-scale', orbitScale.toFixed(3));
          manifestoOrbit.style.setProperty('--chapter-progress', progress.toFixed(3));
        }

        // Phrase calculation (3 phrases total)
        const totalPhrases = manifestoPhrases.length;
        const phraseStep = 1 / totalPhrases;
        const activeIndex = Math.min(totalPhrases - 1, Math.floor(progress / phraseStep));

        manifestoPhrases.forEach((phrase, idx) => {
          const phraseStart = idx * phraseStep;
          const phraseEnd = (idx + 1) * phraseStep;
          const phraseMid = (phraseStart + phraseEnd) / 2;

          let opacity = 0;
          let yOffset = 50;
          let scale = 0.92;
          let blur = 10;

          if (progress >= phraseStart && progress <= phraseEnd) {
            const phaseProgress = (progress - phraseStart) / phraseStep; // 0 to 1
            if (phaseProgress < 0.25) {
              // Fade In
              const inR = phaseProgress / 0.25;
              opacity = inR;
              yOffset = 50 * (1 - inR);
              scale = 0.92 + 0.08 * inR;
              blur = 10 * (1 - inR);
            } else if (phaseProgress > 0.75) {
              // Fade Out
              const outR = (phaseProgress - 0.75) / 0.25;
              opacity = 1 - outR;
              yOffset = -50 * outR;
              scale = 1 - 0.05 * outR;
              blur = 10 * outR;
            } else {
              // Fully Active
              opacity = 1;
              yOffset = 0;
              scale = 1;
              blur = 0;
            }
            phrase.classList.add('active');
          } else {
            phrase.classList.remove('active');
          }

          phrase.style.setProperty('--panel-opacity', opacity.toFixed(2));
          phrase.style.setProperty('--panel-y', `${yOffset.toFixed(1)}px`);
          phrase.style.setProperty('--panel-scale', scale.toFixed(3));
          phrase.style.setProperty('--panel-blur', `${blur.toFixed(1)}px`);
        });

        // Counter UI
        if (manifestoCurrent) {
          manifestoCurrent.textContent = `0${activeIndex + 1}`;
        }
        if (manifestoProgress) {
          manifestoProgress.style.setProperty('--manifesto-fill', `${(progress * 100).toFixed(1)}%`);
        }
      }
    }

    // Lab Sphere Scroll Parallax
    if (labSection && labObject) {
      const rect = labSection.getBoundingClientRect();
      if (rect.top < windowHeight && rect.bottom > 0) {
        const ratio = (windowHeight - rect.top) / (windowHeight + rect.height);
        const rise = (ratio - 0.5) * -40;
        const scale = 0.95 + ratio * 0.1;
        labObject.style.setProperty('--lab-rise', `${rise.toFixed(1)}px`);
        labObject.style.setProperty('--lab-scale', scale.toFixed(3));
      }
    }
  }

  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();

  // --- 4. Work Showcase Carousel Slider ---
  let currentSlideIndex = 0;
  let isTransitioning = false;

  function goToSlide(targetIndex, direction = 'next') {
    if (isTransitioning || targetIndex === currentSlideIndex) return;
    if (targetIndex < 0 || targetIndex >= slides.length) return;

    isTransitioning = true;
    const currentSlide = slides[currentSlideIndex];
    const targetSlide = slides[targetIndex];

    workSlider.setAttribute('data-direction', direction);
    workSlider.classList.add('is-changing');

    targetSlide.classList.add('entering');

    requestAnimationFrame(() => {
      targetSlide.classList.add('entering-now');
    });

    setTimeout(() => {
      currentSlide.classList.remove('active');
      targetSlide.classList.remove('entering', 'entering-now');
      targetSlide.classList.add('active');

      workSlider.classList.remove('is-changing');

      // Update tabs
      tabButtons.forEach((btn, idx) => {
        btn.setAttribute('aria-selected', idx === targetIndex ? 'true' : 'false');
      });

      currentSlideIndex = targetIndex;
      isTransitioning = false;
    }, 650);
  }

  if (prevSlideBtn) {
    prevSlideBtn.addEventListener('click', () => {
      const nextIndex = (currentSlideIndex - 1 + slides.length) % slides.length;
      goToSlide(nextIndex, 'prev');
    });
  }

  if (nextSlideBtn) {
    nextSlideBtn.addEventListener('click', () => {
      const nextIndex = (currentSlideIndex + 1) % slides.length;
      goToSlide(nextIndex, 'next');
    });
  }

  tabButtons.forEach((button) => {
    button.addEventListener('click', () => {
      const index = parseInt(button.dataset.index, 10);
      const dir = index > currentSlideIndex ? 'next' : 'prev';
      goToSlide(index, dir);
    });
  });

  // --- 5. Scroll Observer for Reveal & Telemetry SVG ---
  const observerOptions = {
    root: null,
    rootMargin: '0px 0px -60px 0px',
    threshold: 0.15
  };

  const revealObserver = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        entry.target.classList.add('in-view');
      }
    });
  }, observerOptions);

  document.querySelectorAll('.reveal').forEach((el) => {
    revealObserver.observe(el);
  });
});
